//! Compare synthetic checked identity and special movement against native rows.
use spore_core::{cell_player_movement_v1::{Actor,Route,project},native_sse::Policy};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let b=std::fs::read(std::env::args().nth(1).expect("native rows")).unwrap();assert_eq!(b.len(),400);for i in 0..10{let case=i%5;let actor=Actor{handle:0x10000,kind:if case==1{12}else{11},position:[100f32.to_bits(),100f32.to_bits(),0],velocity:[1f32.to_bits(),2f32.to_bits(),0],flags:0x1230,revision:0xffff};let handle=if case==3{0}else if case==4{0x20000}else{0x10000};let x=project(handle,1,actor,case!=2,11,0.5f32.to_bits(),Policy::Mxcsr1f80,true).unwrap();let decision=match x.route{Route::NoActor=>0,Route::Updated=>1,Route::OtherKind=>2,Route::PredicateFalse=>3};let o=i*40;let expected=[handle,decision,x.actor.position[0],x.actor.position[1],x.actor.position[2],(x.actor.flags as u32)|((x.actor.revision as u32)<<16),x.first_match as u32,x.fresh_match as u32];for(j,v)in expected.iter().enumerate(){assert_eq!(w(&b,o+j*4),*v)}let fp=w(&b,o+32);assert_eq!(fp&0xffff,if i<5{0x27f}else{0x37f});assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(&b,o+36)&!0x3f,0x1f80);}println!("matched ten synthetic actor-identity/movement rows; no live camera or actor claim");}
